from collections import namedtuple


# Per-glyph layout record used by the text-layout pipeline. Each item
# carries the character index, codepoint, and (x, y, font) position.
LayoutItem = namedtuple('LayoutItem',
                        ['ft_object', 'char', 'glyph_idx', 'x', 'prev_kern'])
